fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let len = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(len);
    
    let mut i = 0;
    while i < len {
        // Loop invariant:
        // - 0 <= i <= len
        // - result.len() == i
        // - all elements in result are 1
        result.push(1);
        i += 1;
    }
    
    result
}